{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.final_output_eoq as with main_data as ( select a.*,b.size_tag,c.xs_split,c.s_split,c.m_split,c.l_split,c.xl_split,c.xxl_split from snitch_db.maplemonk.repeat_order_quant_eoq a left join snitch_db.maplemonk.sku_group_xs_without_xs_eoq b on a.skU_group = b.sku_group left join snitch_db.maplemonk.category_size_split_xs_eoq c on a.category = c.category and b.size_tag = c.size_tag ), size_level_split as ( select *, ifnull((order_quantity*xs_split)::int,0) as xs_order_quant, ifnull((order_quantity*s_split)::int,0) as s_order_quant, ifnull((order_quantity*m_split)::int,0) as m_order_quant, ifnull((order_quantity*l_split)::int,0) as l_order_quant, ifnull((order_quantity*xl_split)::int,0) as xl_order_quant, ifnull((order_quantity*xxl_split)::int,0) as xxl_order_quant from main_data ), current_inv as ( select sku_group, ifnull(sum(case when SIZE = \'XS\' OR SIZE = \'28\' then total_inventory end),0) as xs_inv, ifnull(sum(case WHEN SIZE = \'S\' OR SIZE = \'30\' then total_inventory end),0) as s_inv, ifnull(sum(case WHEN SIZE = \'M\' OR SIZE = \'32\' then total_inventory end),0) as m_inv, ifnull(sum(case WHEN SIZE = \'L\' OR SIZE = \'34\' then total_inventory end),0) as l_inv, ifnull(sum(case WHEN SIZE = \'XL\' OR SIZE = \'36\' then total_inventory end),0) as xl_inv, ifnull(sum(case when SIZE IN (\'XXL\', \'XXl\', \'2XL\', \'38\') then total_inventory end),0) as xxl_inv from snitch_db.maplemonk.cut_size_analysis where date = current_date-1 and sku_group in (select sku_group from snitch_db.maplemonk.repeat_decision_eoq where repeat = \'yes\') group by 1 ), sales as ( select sku_group, (ifnull(sum(case when size = \'XS\' then gross_quantity end),0)/30)::int as xs_ros, (ifnull(sum(case when size = \'S\' then gross_quantity end),0)/30)::int as s_ros, (ifnull(sum(case when size = \'M\' then gross_quantity end),0)/30)::int as m_ros, (ifnull(sum(case when size = \'L\' then gross_quantity end),0)/30)::int as l_ros, (ifnull(sum(case when size = \'XL\' then gross_quantity end),0)/30)::int as xl_ros, (ifnull(sum(case when size = \'XXL\' then gross_quantity end),0)/30)::int as xxl_ros from snitch_db.maplemonk.horizontal_sales_categories where sku_group in (select sku_group from snitch_db.maplemonk.repeat_decision_eoq where repeat = \'yes\') and date >= current_date-30 group by 1 ), days_remaining as ( select sku_group, days_remaining from snitch_db.maplemonk.repeat_order_quant_eoq ), total_sales as ( select a.sku_group, xs_ros*b.days_remaining as xs_quant, s_ros*b.days_remaining as s_quant, m_ros*b.days_remaining as m_quant, l_ros*b.days_remaining as l_quant, xl_ros*b.days_remaining as xl_quant, xxl_ros*b.days_remaining as xxl_quant from sales a left join days_remaining b on a.sku_group = b.sku_group ), inv_subtraction as ( select a.sku_group, coalesce(greatest(xs_inv-xs_quant,0),0) as xs_remaining, coalesce(greatest(s_inv-s_quant,0),0) as s_remaining, coalesce(greatest(m_inv-m_quant,0),0) as m_remaining, coalesce(greatest(l_inv-l_quant,0),0) as l_remaining, coalesce(greatest(xl_inv-xl_quant,0),0) as xl_remaining from current_inv a left join total_sales b on a.sku_group = b.sku_group ), final_output as ( select a.sku_group, a.final_ros, a.category, a.l1_category, a.actual_lead_time, a.repeat, a.seasonal, a.min_month, a.max_month, a.inward_date, a.flag, a.days_remaining, a.order_quantity, a.size_tag, a.xs_split, a.s_split, a.m_split, a.l_split, a.xl_split, a.xxl_split, coalesce((a.xs_order_quant-xs_remaining),0) as xs_order_quant, coalesce((a.s_order_quant-s_remaining),0) as s_order_quant, coalesce((a.m_order_quant-m_remaining),0) as m_order_quant, coalesce((a.l_order_quant-l_remaining),0) as l_order_quant, coalesce((a.xl_order_quant-xl_remaining),0) as xl_order_quant, coalesce((a.xxl_order_quant-xs_remaining),0) as xxl_order_quant, case when repeat = \'no\' then 0 when category in (\'Bags\',\'Perfumes\') then order_quantity else (a.xs_order_quant-xs_remaining+a.s_order_quant-s_remaining+a.m_order_quant-m_remaining+a.l_order_quant-l_remaining+a.xl_order_quant-xl_remaining+a.xxl_order_quant-xs_remaining) end as revised_order_quant from size_level_split a left join inv_subtraction b on a.sku_group = b.sku_group ), images as ( SELECT split_part(t.id,\'/\',-1) AS product_id, image.value:\"preview\":\"image\":\"url\"::string AS image_url, ROW_NUMBER() OVER (PARTITION BY t.id ORDER BY image.index) AS image_rank FROM snitch_db.maplemonk.new_meafields_product_products_graph_ql t, LATERAL FLATTEN(input => parse_json(t.media)) AS image WHERE image.value:\"mediaContentType\"::string = \'IMAGE\' ), sku as ( select sku_group, product_name, category, id from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by sku_group order by status desc) = 1 ), sku_details as ( select a.*, category, sku_group, product_name from images a left join sku b on a.product_id::varchar = b.id::varchar where image_rank = 1 qualify row_number() over (partition by sku_group order by product_name) = 1 ), nos as ( select sku_group, tag as nos_tag, from snitch_db.maplemonk.nos qualify row_number() over (partition by sku_group order by nos_tag) = 1 ), already_in_pipeline as ( select adjusted_sku as sku_group, \'yes\' as production_pipeline, type, issued_date, expected_delivery_date, proj_qty from snitch_db.maplemonk.production_data where status != \'Delivered\' and type = \'Repeat\' qualify row_number() over (partition by adjusted_sku order by issued_date desc) = 1 ) select a.*, b.product_name as title, b.image_url as preview_image, case when c.nos_tag in (\'Offline\',\'Online\') then \'yes\' else \'no\' end as nos_flag, coalesce(d.production_pipeline,\'no\') as production_pipeline from final_output a left join sku_details b on a.sku_group = b.sku_group left join nos c on a.sku_group = c.sku_group left join already_in_pipeline d on a.sku_group = d.sku_group ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            